type IconProps = {
  name: IconName;
  size?: number;
  color?: string;
};

export default function Icon({ name, size = 24, color }: IconProps) {
  const { colors } = useTheme();
  const fill = color ?? colors.icon;
  const def = ICONS[name];
  return (
    <Svg width={size} height={size} viewBox={def.viewBox} fill="none">
      {def.paths.map((d, i) =>
        def.stroke
          ? <Path key={i} d={d} stroke={fill} strokeWidth={def.strokeWidth ?? 2} strokeLinecap="round" strokeLinejoin="round" />
          : <Path key={i} d={d} fill={fill} />
      )}
    </Svg>
  );
}
